using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputStagePreviewProof {
 static int words;
 static void Check(string folder,string label,List<float[]> rows){byte[] expected=File.ReadAllBytes(Path.Combine(folder,label+"-items.bin"));int at=0;foreach(var row in rows){int count=(int)BitConverter.ToSingle(expected,at);if(row.Length!=count)throw new Exception(label+" record length at "+at+": "+row.Length+" != "+count);for(int i=0;i<row.Length;i++){if(BitConverter.ToInt32(BitConverter.GetBytes(row[i]),0)!=BitConverter.ToInt32(expected,at+4+i*4))throw new Exception(label+" word at "+at+" P"+(i+1));words++;}at+=(count+1)*4;}}
 static int Main(string[] a){try{var tx=new InputStaffTransaction(1,0,0,200,1,25,.005f,0,1);var prefix=new List<float[]>{new InputSetupState().StaffRecord()};tx.Pitches(InputTextLists.Pitches("TR/C4:E4:G4/C4:E4:G4;",new InputPitchState()),true);Check(a[0],"pitches",tx.Preview(prefix));tx.Rhythms(InputTextLists.Rhythms("Q/Q;"));Check(a[0],"rhythms",tx.Preview(prefix));var marks=InputMarkText.Parse("P 1;");tx.Marks(marks.Values,marks.Opposite);Check(a[0],"marks",tx.Preview(prefix));tx.Beams(new float[0]);Check(a[0],"beams",tx.Preview(prefix));tx.Slurs(InputEndpointText.Parse("1 2;",false,4,4).Pairs);Check(a[0],"slurs",tx.Commit(prefix));Console.WriteLine("PASS all five original visible stage previews, "+words+" exact compact parameter words");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
